module top;
  reg a
  initial a = 0;
endmodule

module top;
  reg a;
  initial a =< 1;
endmodule

module top;
  reg a;
  initial if (a = 1) $display("yes");
endmodule

module top;
  reg q;
  alwyas @(*) q = 0;
endmodule

module top;
  reg q;
  initial q = 0;

module top;
  reg a, b;
  initial if (a)
    a = 0;
    b = 1;
  else
    b = 0;
endmodule

module top;
  reg clk, q;
  always @(posedge clk q <= 1;
endmodule

module top;
  wire q;
  initial q = 1;
endmodule

module top;
  reg q;
  assign q = 1;
endmodule

module top;
  reg counter;
  initial $display("%b", countr);
endmodule

module top;
  initial $display("%b", missing_signal);
endmodule

module top;
  wire led_out;
  assign led_ou = 1'b1;
endmodule

module top;
  assign answer = 1'b1;
endmodule

module top;
  adder u1();
endmodule

module child(input a, output y); assign y = a; endmodule
module top;
  child u1(.input_a(1'b0), .y());
endmodule

module child #(parameter WIDTH=4) (); endmodule
module top;
  child #(.WIDHT(8)) u1();
endmodule

module child(input a, input b, output y); assign y = a & b; endmodule
module top;
  wire out;
  child u1(1'b0, 1'b1, out, 1'b0);
endmodule

module child(input [3:0] data); endmodule
module top;
  wire [7:0] data = 8'haa;
  child u1(.data(data));
endmodule

module child(output [7:0] data); assign data = 8'haa; endmodule
module top;
  wire [3:0] data;
  child u1(.data(data));
endmodule

module top;
  reg [3:0] data;
  initial $display("%b", data[5]);
endmodule

module top;
  reg [7:0] data;
  initial $display("%b", data[0:3]);
endmodule

module top;
  reg [0:-1] data;
  initial $display("%b", data);
endmodule

module top;
  wire x;
  reg x;
endmodule

module top;
  reg x;
  initial x=0;
  initial x=1;
endmodule

module top;
  wire [3:0] narrowed;
  assign narrowed = 8'hff;
  initial #1 $display("narrowed=%h", narrowed);
endmodule

module top;
  reg [3:0] data;
  initial begin data = 4'd31; $display("data=%d", data); end
endmodule

module top;
  reg en, data, q;
  always @(*) if (en) q = data;
  initial begin en=0; data=1; #1 $display("q=%b",q); end
endmodule

module top;
  reg clk=0, a=0, b=0;
  always @(posedge clk) begin a = 1; b = a; end
  initial begin #1 clk=1; #1 $display("a=%b b=%b",a,b); end
endmodule

module top;
  integer a, b;
  initial begin a=7; b=0; $display("quotient=%d", a / b); end
endmodule

module top;
  reg [3:0] a;
  initial a = 4'b1020;
endmodule

module top;
  reg [1:0] a; reg b;
  initial begin
    case(a)
      0: b=0;
      1: b=1;
  end
endmodule

module top;
  initial begin
    $display("hello");

module top;
  initial $disply("hi");
endmodule

module child(input data, output result); assign result = data; endmodule
module top;
  wire y;
  child u1(.dtaa(1'b0), .result(y));
endmodule

module top;
  reg [3:0] x;
  initial $display("%b",x[7:2]);
endmodule

module top;
  initial $display("%d", `MAX_COUNT);
endmodule

module top;
  reg a,b;
  initial begin
    case(a)
      0 b = 0;
      default: b = 1;
    endcase
  end
endmodule

module top;
  reg a=1,b=0,c=0;
  initial if (a)
    b = 1;
    c = 1;
endmodule

module top;
  reg [3:0] count;
  initial $display("%d", countr);
endmodule

module top;
 reg a;
 initial begin
  a = 1
 end
endmodule

module top;
  wire x;
  assign x=1'b0;
  assign x=1'b1;
  initial #1 $display("x=%b",x);
endmodule

module top;
 reg a=0;
 initial begin if (a <= 1) $display("yes"); end
endmodule

module top;
 initial begin #1 $fatal(1, "failure example"); end
endmodule
